"""Lazy, composable iteration specifications for :func:`glom.glom`."""

import itertools

from boltons.iterutils import chunked_iter, windowed_iter, split_iter

from .core import (T, Path, TargetRegistry, glom, CheckError, SKIP, STOP,
                   _MISSING)


def _iterate(target, scope):
    handler = scope[TargetRegistry].get_handler('iterate', target,
                                                path=scope[Path])
    return iter(handler(target))


def _matches(target, spec, scope):
    try:
        result = scope[glom](target, spec, scope)
    except CheckError:
        return False
    return result is not SKIP and result is not STOP and bool(result)


class First(object):
    """Return the first item satisfying *key*, or *default* (None).

    *key* is a glom spec, evaluated separately against each item. Failed
    Check specifications count as non-matches, just like false results.
    """
    def __init__(self, key=T, default=None):
        self.key = key
        self.default = default

    def glomit(self, target, scope):
        for item in _iterate(target, scope):
            if _matches(item, self.key, scope):
                return item
        return self.default

    def __repr__(self):
        return 'First(%r, default=%r)' % (self.key, self.default)


class Iter(object):
    """Lazily apply *subspec* to an iterable target.

    Chain transformations such as ``Iter('value').filter().chunked(2)``.
    Each method returns a new specification; existing chains are unchanged.
    ``all()`` collects results into a list and ``first()`` selects a result.
    SKIP omits a mapped item and *sentinel* (STOP by default) ends iteration.
    """
    def __init__(self, subspec=T, sentinel=STOP):
        self.subspec = subspec
        self.sentinel = sentinel
        self._steps = ()

    def _chain(self, operation, *args):
        ret = type(self)(self.subspec, sentinel=self.sentinel)
        ret._steps = self._steps + ((operation, args),)
        return ret

    def map(self, subspec):
        """Apply *subspec* to each result, respecting SKIP and STOP."""
        return self._chain('map', subspec)

    def filter(self, key=T):
        """Keep items whose *key* spec evaluates to a true value."""
        return self._chain('filter', key)

    def chunked(self, size, fill=_MISSING):
        """Group items into lists of *size*, optionally padding the last."""
        if not isinstance(size, int) or size <= 0:
            raise ValueError('chunk size must be a positive integer')
        return self._chain('chunked', size, fill)

    def flatten(self):
        """Flatten one level of nested iterables."""
        return self._chain('flatten')

    def dropwhile(self, key=T):
        """Drop items while *key* is true, then yield all remaining items."""
        return self._chain('dropwhile', key)

    def takewhile(self, key=T):
        """Yield items until *key* is false."""
        return self._chain('takewhile', key)

    def unique(self, key=T):
        """Keep the first item for each distinct result of *key*."""
        return self._chain('unique', key)

    def slice(self, *args):
        """Select a slice using itertools.islice semantics."""
        # Validate even if the eventual input iterable is empty.
        itertools.islice((), *args)
        return self._chain('slice', *args)

    def limit(self, count):
        """Yield at most *count* items."""
        return self.slice(count)

    def windowed(self, size):
        """Yield overlapping tuples of *size* items."""
        return self._chain('windowed', size)

    def split(self, sep=None, maxsplit=None):
        """Split an iterable into lists using boltons split semantics."""
        return self._chain('split', sep, maxsplit)

    def all(self):
        """Collect the entire stream into a list."""
        return _IterResult(self, list)

    def first(self, key=T, default=None):
        """Return the first matching item, or *default*."""
        return _IterResult(self, First(key, default=default))

    def _map(self, iterable, subspec, scope):
        for index, item in enumerate(iterable):
            child = scope.new_child({Path: scope[Path] + [index]})
            result = scope[glom](item, subspec, child)
            if result is self.sentinel:
                break
            if result is not SKIP:
                yield result

    def _filter(self, iterable, key, scope):
        for item in iterable:
            if _matches(item, key, scope):
                yield item

    def _unique(self, iterable, key, scope):
        seen = set()
        for item in iterable:
            value = scope[glom](item, key, scope)
            if value not in seen:
                seen.add(value)
                yield item

    def _while(self, iterable, key, scope, drop):
        predicate = lambda item: _matches(item, key, scope)
        factory = itertools.dropwhile if drop else itertools.takewhile
        return factory(predicate, iterable)

    def _flatten(self, iterable, scope):
        for item in iterable:
            for value in _iterate(item, scope):
                yield value

    def glomit(self, target, scope):
        iterator = self._map(_iterate(target, scope), self.subspec, scope)
        for operation, args in self._steps:
            if operation == 'map':
                iterator = self._map(iterator, args[0], scope)
            elif operation == 'filter':
                iterator = self._filter(iterator, args[0], scope)
            elif operation == 'chunked':
                size, fill = args
                kw = {} if fill is _MISSING else {'fill': fill}
                iterator = chunked_iter(iterator, size, **kw)
            elif operation == 'flatten':
                iterator = self._flatten(iterator, scope)
            elif operation in ('dropwhile', 'takewhile'):
                iterator = self._while(iterator, args[0], scope,
                                       operation == 'dropwhile')
            elif operation == 'unique':
                iterator = self._unique(iterator, args[0], scope)
            elif operation == 'slice':
                iterator = itertools.islice(iterator, *args)
            elif operation == 'windowed':
                iterator = windowed_iter(iterator, args[0])
            elif operation == 'split':
                iterator = split_iter(iterator, *args)
        return iterator

    def __repr__(self):
        result = 'Iter(%r)' % (self.subspec,)
        for name, args in self._steps:
            result += '.%s(%s)' % (name, ', '.join(repr(arg) for arg in args))
        return result


class _IterResult(object):
    def __init__(self, iterable, result):
        self.iterable = iterable
        self.result = result

    def glomit(self, target, scope):
        iterator = scope[glom](target, self.iterable, scope)
        return scope[glom](iterator, self.result, scope)

    def __repr__(self):
        if self.result is list:
            return '%r.all()' % (self.iterable,)
        return '%r.first(%r, default=%r)' % (self.iterable,
                                           self.result.key, self.result.default)
